  root.innerHTML = `${(renderers[page] || homePage)()}${toastMarkup()}`;
  bindCommon();
  initHeroCinema();
  initAgendaImage();
  initHeaderThemes();
  initScrollHeader();
  bindModal();
  bindReservationModules();
  scrollToReveal();
})();

